using System;using System.Windows;using System.Windows.Controls;using DualSteam.UI;
public sealed class ProcessDetails:StackPanel {
 readonly TextBlock count,memory,cpu,pid,uptime,state;double priorCpu;DateTime priorAt;long priorStart;
 public ProcessDetails(string title){Children.Add(Ui.Text(title,14,"text.primary",true));var metrics=new System.Windows.Controls.Primitives.UniformGrid{Columns=4,Margin=new Thickness(0,16,0,12)};count=Metric(metrics,"Processes");memory=Metric(metrics,"Memory");cpu=Metric(metrics,"CPU");pid=Metric(metrics,"Process ID");memory.Text="0 MB";cpu.Text="0.0%";Children.Add(metrics);state=Ui.Text("Not running",12,"text.muted");Children.Add(state);uptime=Ui.Text("",12,"text.muted");uptime.Margin=new Thickness(0,4,0,0);Children.Add(uptime);SizeChanged+=(s,e)=>{double scale=Convert.ToDouble(Theme.Resources["type.14"])/14;metrics.Columns=ActualWidth<320*scale?2:4;};}
 static TextBlock Metric(Panel parent,string title){var stack=new StackPanel();stack.Children.Add(Ui.Text(title,12,"text.muted"));var value=Ui.Text("0",14,"text.primary",true);value.Margin=new Thickness(0,6,0,0);stack.Children.Add(value);parent.Children.Add(stack);return value;}
 public void Update(PerformanceSnapshot s){var now=DateTime.UtcNow;double usage=priorStart==s.Started&&priorAt!=default(DateTime)&&(now-priorAt).TotalMilliseconds>0?Math.Max(0,Math.Min(100,(s.Cpu-priorCpu)/(now-priorAt).TotalMilliseconds/Environment.ProcessorCount*100)):0;count.Text=s.Count.ToString();memory.Text=(s.Memory/1048576d).ToString("N0")+" MB";cpu.Text=usage.ToString("0.0")+"%";pid.Text=s.Root.ToString();state.Text=s.Root==0?"Not running":s.Ready?"Interface ready":"Starting / waiting for interface";var elapsed=s.Root==0?TimeSpan.Zero:now-new DateTime(s.Started,DateTimeKind.Utc);uptime.Text=s.Root==0?"":"Uptime · "+Math.Max(0,(int)elapsed.TotalHours)+"h "+Math.Max(0,elapsed.Minutes)+"m";priorCpu=s.Cpu;priorAt=now;priorStart=s.Started;}
}
